INSERT INTO options (id, question_id, teks, poin, umpan_balik) VALUES
('o5-A1-1', 'q5000001-0000-0000-0000-000000000001', 'Produk yang sudah dirilis ke pengguna', 0, 'Keliru. Produk yang sudah dirilis adalah versi produksi (live product), bukan prototype.'),
('o5-A1-2', 'q5000001-0000-0000-0000-000000000001', 'Representasi awal produk untuk diuji dan divalidasi', 10, 'Tepat! Prototype adalah simulasi atau representasi awal produk guna menguji alur serta memvalidasi desain.'),
('o5-A1-3', 'q5000001-0000-0000-0000-000000000001', 'Dokumen kebutuhan sistem', 0, 'Keliru. Dokumen kebutuhan sistem adalah PRD atau SRS, bukan prototype.'),
('o5-A1-4', 'q5000001-0000-0000-0000-000000000001', 'Struktur database', 0, 'Keliru. Struktur database merupakan skema penyimpanan data di sisi back-end.'),
('o5-A2-1', 'q5000001-0000-0000-0000-000000000002', 'Menentukan harga produk', 0, 'Keliru. Penentuan harga termasuk strategi monetisasi/bisnis.'),
('o5-A2-2', 'q5000001-0000-0000-0000-000000000002', 'Menguji ide dan mendapatkan feedback pengguna', 10, 'Tepat! Tujuan utama prototype adalah memvalidasi ide dan mengumpulkan umpan balik nyata dari pengguna.'),
('o5-A2-3', 'q5000001-0000-0000-0000-000000000002', 'Membuat server aplikasi', 0, 'Keliru. Pembuatan server termasuk ranah DevOps dan back-end engineering.'),
('o5-A2-4', 'q5000001-0000-0000-0000-000000000002', 'Mencari investor', 0, 'Keliru. Mencari investor adalah tujuan pitching bisnis, bukan tujuan utama pembuatan prototype.'),
('o5-A3-1', 'q5000001-0000-0000-0000-000000000003', 'Mengurangi biaya validasi desain', 10, 'Tepat! Prototype memungkinkan tim menguji konsep jauh lebih murah sebelum menulis kode program.'),
('o5-A3-2', 'q5000001-0000-0000-0000-000000000003', 'Menghilangkan kebutuhan pengguna', 0, 'Keliru. Prototype justru dibuat untuk menguji kesesuaian produk dengan kebutuhan pengguna.'),
('o5-A3-3', 'q5000001-0000-0000-0000-000000000003', 'Meningkatkan ukuran file aplikasi', 0, 'Keliru. Ukuran file aplikasi tidak berkaitan dengan fungsi prototype.'),
('o5-A3-4', 'q5000001-0000-0000-0000-000000000003', 'Mengganti proses coding', 0, 'Keliru. Prototype adalah acuan sebelum proses coding, bukan pengganti pengembangan produk.'),
('o5-A4-1', 'q5000001-0000-0000-0000-000000000004', 'Struktur sederhana dan detail minimal', 10, 'Tepat! Low-Fidelity Prototype berfokus pada struktur dasar, tata letak, dan alur tanpa detail visual rumit.'),
('o5-A4-2', 'q5000001-0000-0000-0000-000000000004', 'Animasi lengkap', 0, 'Keliru. Animasi lengkap merupakan ciri High-Fidelity Prototype.'),
('o5-A4-3', 'q5000001-0000-0000-0000-000000000004', 'Warna final produk', 0, 'Keliru. Low-Fidelity umumnya menggunakan skala abu-abu (grayscale) atau sketsa kasar.'),
('o5-A4-4', 'q5000001-0000-0000-0000-000000000004', 'Database lengkap', 0, 'Keliru. Prototype tidak terhubung dengan database produksi.'),
('o5-A5-1', 'q5000001-0000-0000-0000-000000000005', 'Sangat sederhana dan tanpa interaksi', 0, 'Keliru. Itu adalah karakteristik sketsa kasar atau wireframe statis.'),
('o5-A5-2', 'q5000001-0000-0000-0000-000000000005', 'Menyerupai produk akhir secara visual dan interaksi', 10, 'Tepat! High-Fidelity Prototype sudah menggunakan warna, tipografi, komponen UI, dan transisi yang mendekati aplikasi asli.'),
('o5-A5-3', 'q5000001-0000-0000-0000-000000000005', 'Hanya berupa tulisan', 0, 'Keliru. Prototype berwujud visual antarmuka, bukan dokumen teks saja.'),
('o5-A5-4', 'q5000001-0000-0000-0000-000000000005', 'Tidak dapat diuji', 0, 'Keliru. High-Fidelity Prototype sangat ideal untuk diuji dalam sesi Usability Testing.'),
('o5-A6-1', 'q5000001-0000-0000-0000-000000000006', 'Mengurangi risiko kesalahan desain', 10, 'Tepat! Masalah alur dan antarmuka dapat dideteksi serta diperbaiki sebelum developer menulis kode.'),
('o5-A6-2', 'q5000001-0000-0000-0000-000000000006', 'Menambah bug aplikasi', 0, 'Keliru. Prototype justru mencegah bug desain dan miskomunikasi spesifikasi.'),
('o5-A6-3', 'q5000001-0000-0000-0000-000000000006', 'Menghilangkan kebutuhan testing', 0, 'Keliru. Pengujian tetap wajib dilakukan pada tahap pengembangan maupun pasca-integrasi.'),
('o5-A6-4', 'q5000001-0000-0000-0000-000000000006', 'Mengurangi jumlah pengguna', 0, 'Keliru. Validasi prototype membantu meningkatkan kepuasan dan retensi pengguna.'),
('o5-A7-1', 'q5000001-0000-0000-0000-000000000007', 'Figma', 10, 'Tepat! Figma adalah standar industri untuk merancang UI dan membuat clickable prototype kolaboratif.'),
('o5-A7-2', 'q5000001-0000-0000-0000-000000000007', 'MySQL', 0, 'Keliru. MySQL adalah sistem manajemen basis data relasional (RDBMS).'),
('o5-A7-3', 'q5000001-0000-0000-0000-000000000007', 'PostgreSQL', 0, 'Keliru. PostgreSQL adalah sistem database relasional, bukan alat desain UI.'),
('o5-A7-4', 'q5000001-0000-0000-0000-000000000007', 'VS Code', 0, 'Keliru. VS Code adalah code editor untuk menulis kode program.'),
('o5-A8-1', 'q5000001-0000-0000-0000-000000000008', 'Flow Connection', 0, 'Keliru. Istilah baku yang digunakan adalah Interaction Link.'),
('o5-A8-2', 'q5000001-0000-0000-0000-000000000008', 'Trigger Link', 0, 'Keliru. Trigger adalah pemicu aksi (seperti On Click), sedangkan penghubung antar layarnya disebut Interaction Link.'),
('o5-A8-3', 'q5000001-0000-0000-0000-000000000008', 'Interaction Link', 10, 'Tepat! Interaction Link menghubungkan elemen pemicu pada satu layar ke layar tujuan pada prototype.'),
('o5-A8-4', 'q5000001-0000-0000-0000-000000000008', 'Navigation Connection', 0, 'Keliru. Istilah yang tepat sesuai materi adalah Interaction Link.'),
('o5-A9-1', 'q5000001-0000-0000-0000-000000000009', 'Mensimulasikan pengalaman pengguna', 10, 'Tepat! Prototype interaktif memberi gambaran nyata bagaimana pengguna bernavigasi dan berinteraksi.'),
('o5-A9-2', 'q5000001-0000-0000-0000-000000000009', 'Menjalankan backend', 0, 'Keliru. Prototype hanya mensimulasikan sisi antarmuka tanpa logika server sungguhan.'),
('o5-A9-3', 'q5000001-0000-0000-0000-000000000009', 'Menyimpan data pengguna', 0, 'Keliru. Penyimpanan data permanen membutuhkan database di back-end.'),
('o5-A9-4', 'q5000001-0000-0000-0000-000000000009', 'Mengelola server', 0, 'Keliru. Pengelolaan server bukan fungsi dari prototype.'),
('o5-A10-1', 'q5000001-0000-0000-0000-000000000010', 'Menampilkan database', 0, 'Keliru. Tabel atau daftar lebih tepat untuk menampilkan kumpulan data.'),
('o5-A10-2', 'q5000001-0000-0000-0000-000000000010', 'Memicu suatu aksi atau navigasi', 10, 'Tepat! Button adalah elemen interaktif utama untuk menjalankan perintah (submit, simpan) atau berpindah halaman.'),
('o5-A10-3', 'q5000001-0000-0000-0000-000000000010', 'Menyimpan source code', 0, 'Keliru. Source code disimpan di repository seperti GitHub.'),
('o5-A10-4', 'q5000001-0000-0000-0000-000000000010', 'Menjalankan server', 0, 'Keliru. Menjalankan server dilakukan melalui terminal/infrastruktur hosting.'),
('o5-B1-1', 'q5000003-0000-0000-0000-000000000001', 'Menampilkan gambar', 0, 'Keliru. Komponen gambar menggunakan Image container/tag <img>.'),
('o5-B1-2', 'q5000003-0000-0000-0000-000000000001', 'Memasukkan data oleh pengguna', 10, 'Tepat! Input Field memungkinkan pengguna mengetikkan teks, angka, email, atau kata sandi ke dalam sistem.'),
('o5-B1-3', 'q5000003-0000-0000-0000-000000000001', 'Menyimpan database', 0, 'Keliru. Input field hanya menerima masukan di sisi antarmuka.'),
('o5-B1-4', 'q5000003-0000-0000-0000-000000000001', 'Menghubungkan jaringan', 0, 'Keliru. Koneksi jaringan tidak diatur oleh komponen form UI.'),
('o5-B2-1', 'q5000003-0000-0000-0000-000000000002', 'Hanya ada satu pilihan', 0, 'Keliru. Jika hanya satu opsi konfirmasi, cukup gunakan checkbox tunggal atau tombol.'),
('o5-B2-2', 'q5000003-0000-0000-0000-000000000002', 'Pengguna perlu memilih dari beberapa opsi', 10, 'Tepat! Dropdown menyajikan daftar pilihan secara ringkas dan menghemat ruang layar saat opsi cukup banyak.'),
('o5-B2-3', 'q5000003-0000-0000-0000-000000000002', 'Menampilkan video', 0, 'Keliru. Pemutar video menggunakan komponen media/video player.'),
('o5-B2-4', 'q5000003-0000-0000-0000-000000000002', 'Membuka aplikasi', 0, 'Keliru. Dropdown adalah komponen pemilihan opsi di dalam formulir atau menu.'),
('o5-B3-1', 'q5000003-0000-0000-0000-000000000003', 'Memilih satu pilihan saja', 0, 'Keliru. Memilih satu opsi dari beberapa pilihan adalah fungsi Radio Button.'),
('o5-B3-2', 'q5000003-0000-0000-0000-000000000003', 'Memilih lebih dari satu pilihan', 10, 'Tepat! Checkbox memungkinkan pengguna mencentang nol, satu, atau beberapa opsi sekaligus.'),
('o5-B3-3', 'q5000003-0000-0000-0000-000000000003', 'Menampilkan halaman baru', 0, 'Keliru. Navigasi ke halaman baru menggunakan tautan (link) atau tombol.'),
('o5-B3-4', 'q5000003-0000-0000-0000-000000000003', 'Menghapus data', 0, 'Keliru. Aksi menghapus data menggunakan tombol aksi (action button).'),
('o5-B4-1', 'q5000003-0000-0000-0000-000000000004', 'Memilih beberapa opsi sekaligus', 0, 'Keliru. Memilih beberapa opsi sekaligus adalah fungsi Checkbox.'),
('o5-B4-2', 'q5000003-0000-0000-0000-000000000004', 'Memilih satu opsi dari beberapa pilihan', 10, 'Tepat! Radio Button bersifat mutually exclusive (hanya satu opsi yang dapat dipilih dalam satu grup).'),
('o5-B4-3', 'q5000003-0000-0000-0000-000000000004', 'Menampilkan gambar', 0, 'Keliru. Radio button adalah komponen input pilihan pada formulir.'),
('o5-B4-4', 'q5000003-0000-0000-0000-000000000004', 'Membuat akun', 0, 'Keliru. Pembuatan akun dipicu oleh tombol submit pada form registrasi.'),
('o5-B5-1', 'q5000003-0000-0000-0000-000000000005', 'Mengaktifkan atau menonaktifkan suatu fitur', 10, 'Tepat! Toggle Switch merepresentasikan dua kondisi biner (ON/OFF) yang langsung berlaku.'),
('o5-B5-2', 'q5000003-0000-0000-0000-000000000005', 'Menghapus akun', 0, 'Keliru. Aksi destruktif seperti menghapus akun memerlukan tombol konfirmasi eksplisit.'),
('o5-B5-3', 'q5000003-0000-0000-0000-000000000005', 'Menutup aplikasi', 0, 'Keliru. Menutup tampilan biasanya menggunakan tombol Close (X).'),
('o5-B5-4', 'q5000003-0000-0000-0000-000000000005', 'Menyimpan data', 0, 'Keliru. Menyimpan formulir menggunakan tombol Simpan/Submit.'),
('o5-B6-1', 'q5000003-0000-0000-0000-000000000006', 'Membuat pengguna lebih mudah memahami antarmuka', 10, 'Tepat! Konsistensi pola komponen, warna, dan penempatan menurunkan beban kognitif pengguna.'),
('o5-B6-2', 'q5000003-0000-0000-0000-000000000006', 'Membuat file lebih besar', 0, 'Keliru. Komponen yang konsisten justru membuat desain lebih efisien dan terstruktur.'),
('o5-B6-3', 'q5000003-0000-0000-0000-000000000006', 'Mengurangi fitur', 0, 'Keliru. Konsistensi mengatur keseragaman desain, bukan pemangkasan fitur.'),
('o5-B6-4', 'q5000003-0000-0000-0000-000000000006', 'Menambah kompleksitas', 0, 'Keliru. Konsistensi justru menyederhanakan kurva belajar pengguna.'),
('o5-B7-1', 'q5000003-0000-0000-0000-000000000007', 'Memvalidasi desain dengan pengguna nyata', 10, 'Tepat! User Testing menguji apakah target pengguna benar-benar dapat menggunakan desain dengan lancar.'),
('o5-B7-2', 'q5000003-0000-0000-0000-000000000007', 'Menjual produk', 0, 'Keliru. Penjualan adalah aktivitas komersial/marketing, bukan tujuan User Testing.'),
('o5-B7-3', 'q5000003-0000-0000-0000-000000000007', 'Menentukan harga', 0, 'Keliru. Penentuan harga termasuk riset pasar dan model bisnis.'),
('o5-B7-4', 'q5000003-0000-0000-0000-000000000007', 'Mengatur server', 0, 'Keliru. Pengaturan server merupakan tugas teknis infrastruktur.'),
('o5-B8-1', 'q5000003-0000-0000-0000-000000000008', 'Memperbaiki prototype', 10, 'Tepat! Setiap temuan dan masukan pengguna dijadikan dasar iterasi penyempurnaan prototype.'),
('o5-B8-2', 'q5000003-0000-0000-0000-000000000008', 'Menghapus seluruh desain', 0, 'Keliru. Feedback digunakan untuk mengevaluasi dan memperbaiki bagian yang bermasalah.'),
('o5-B8-3', 'q5000003-0000-0000-0000-000000000008', 'Menentukan gaji tim', 0, 'Keliru. Umpan balik UX tidak berkaitan dengan penggajian tim.'),
('o5-B8-4', 'q5000003-0000-0000-0000-000000000008', 'Mengurangi kualitas produk', 0, 'Keliru. Feedback justru meningkatkan kualitas dan kegunaan produk.'),
('o5-B9-1', 'q5000003-0000-0000-0000-000000000009', 'Elemen yang mengarahkan pengguna melakukan tindakan tertentu', 10, 'Tepat! Call To Action (CTA) mendorong pengguna mengambil langkah utama seperti Daftar, Mulai Belajar, atau Beli.'),
('o5-B9-2', 'q5000003-0000-0000-0000-000000000009', 'Database aplikasi', 0, 'Keliru. CTA adalah elemen antarmuka pengguna, bukan penyimpanan data.'),
('o5-B9-3', 'q5000003-0000-0000-0000-000000000009', 'Struktur navigasi', 0, 'Keliru. Struktur navigasi mengatur perpindahan antar halaman secara keseluruhan.'),
('o5-B9-4', 'q5000003-0000-0000-0000-000000000009', 'Jenis wireframe', 0, 'Keliru. CTA adalah komponen interaktif di dalam layar, bukan jenis wireframe.'),
('o5-B10-1', 'q5000003-0000-0000-0000-000000000010', 'Tujuan dan CTA yang jelas', 10, 'Tepat! Landing page yang efektif langsung menyampaikan nilai utama dan mengarahkan pengunjung pada satu CTA jelas.'),
('o5-B10-2', 'q5000003-0000-0000-0000-000000000010', 'Banyak warna acak', 0, 'Keliru. Warna acak merusak hierarki visual dan identitas merek.'),
('o5-B10-3', 'q5000003-0000-0000-0000-000000000010', 'Banyak pop-up', 0, 'Keliru. Terlalu banyak pop-up mengganggu pengalaman pengguna.'),
('o5-B10-4', 'q5000003-0000-0000-0000-000000000010', 'Navigasi yang membingungkan', 0, 'Keliru. Navigasi landing page harus sederhana dan terarah.'),
('o5-C1-1', 'q5000005-0000-0000-0000-000000000001', 'Tahap coding penuh', 10, 'Tepat! Menguji prototype sebelum coding penuh menghemat biaya dan waktu rekayasa perangkat lunak.'),
('o5-C1-2', 'q5000005-0000-0000-0000-000000000001', 'Ide ditemukan', 0, 'Keliru. Ide dan rumusan masalah harus ada terlebih dahulu sebelum membuat prototype.'),
('o5-C1-3', 'q5000005-0000-0000-0000-000000000001', 'Riset pengguna', 0, 'Keliru. Riset pengguna dilakukan di awal untuk memahami masalah sebelum merancang solusi.'),
('o5-C1-4', 'q5000005-0000-0000-0000-000000000001', 'Pembuatan wireframe', 0, 'Keliru. Wireframe dibuat terlebih dahulu sebagai kerangka sebelum prototype.'),
('o5-C2-1', 'q5000005-0000-0000-0000-000000000002', 'Konsisten dan mudah dipahami', 10, 'Tepat! Navigasi yang konsisten membuat pengguna selalu tahu posisi mereka dan ke mana harus melangkah.'),
('o5-C2-2', 'q5000005-0000-0000-0000-000000000002', 'Rumit dan kompleks', 0, 'Keliru. Navigasi yang rumit memicu frustrasi dan membuat pengguna meninggalkan aplikasi.'),
('o5-C2-3', 'q5000005-0000-0000-0000-000000000002', 'Berubah pada setiap halaman', 0, 'Keliru. Menu navigasi yang berubah-ubah merusak konsistensi dan membingungkan pengguna.'),
('o5-C2-4', 'q5000005-0000-0000-0000-000000000002', 'Memiliki banyak cabang tidak perlu', 0, 'Keliru. Cabang menu berlebihan menyebabkan cognitive overload.'),
('o5-C3-1', 'q5000005-0000-0000-0000-000000000003', 'Prototype yang dapat diklik dan diuji alurnya', 10, 'Tepat! Clickable prototype memungkinkan penguji berinteraksi langsung dengan tombol dan tautan antar layar.'),
('o5-C3-2', 'q5000005-0000-0000-0000-000000000003', 'Produk yang sudah dijual', 0, 'Keliru. Clickable prototype masih berupa simulasi desain, bukan produk komersial.'),
('o5-C3-3', 'q5000005-0000-0000-0000-000000000003', 'Aplikasi yang sudah online', 0, 'Keliru. Aplikasi online adalah produk yang sudah dideploy ke server produksi.'),
('o5-C3-4', 'q5000005-0000-0000-0000-000000000003', 'Sistem yang sudah memiliki database', 0, 'Keliru. Clickable prototype tidak memerlukan database sungguhan.'),
('o5-C4-1', 'q5000005-0000-0000-0000-000000000004', 'Memberikan simulasi yang mendekati produk akhir', 10, 'Tepat! High-Fidelity Prototype menghadirkan visual, micro-interaction, dan alur yang sangat realistis.'),
('o5-C4-2', 'q5000005-0000-0000-0000-000000000004', 'Menghilangkan testing', 0, 'Keliru. Justru High-Fidelity Prototype dibuat agar testing terasa lebih realistis.'),
('o5-C4-3', 'q5000005-0000-0000-0000-000000000004', 'Mengganti coding sepenuhnya', 0, 'Keliru. Desain tetap perlu diterjemahkan ke kode front-end dan back-end.'),
('o5-C4-4', 'q5000005-0000-0000-0000-000000000004', 'Mengurangi jumlah pengguna', 0, 'Keliru. High-Fidelity membantu memastikan produk mudah dipakai oleh target pengguna.'),
('o5-C5-1', 'q5000005-0000-0000-0000-000000000005', 'Sulit digunakan pengguna', 0, 'Keliru. Prototype yang baik harus intuitif dan mudah diuji.'),
('o5-C5-2', 'q5000005-0000-0000-0000-000000000005', 'Mampu mendukung pengujian kebutuhan pengguna', 10, 'Tepat! Indikator utama prototype yang baik adalah kemampuannya memvalidasi alur penyelesaian masalah pengguna.'),
('o5-C5-3', 'q5000005-0000-0000-0000-000000000005', 'Memiliki ukuran file besar', 0, 'Keliru. Ukuran file besar bukan ukuran kualitas UX.'),
('o5-C5-4', 'q5000005-0000-0000-0000-000000000005', 'Menggunakan banyak warna', 0, 'Keliru. Penggunaan banyak warna tanpa hierarki justru mengganggu fokus pengguna.'),
('o5-C6-1', 'q5000005-0000-0000-0000-000000000006', 'Wireframing', 10, 'Tepat! Setelah kerangka tata letak (wireframe) tersusun, desain ditingkatkan menjadi prototype interaktif.'),
('o5-C6-2', 'q5000005-0000-0000-0000-000000000006', 'Deployment', 0, 'Keliru. Deployment adalah tahap merilis aplikasi yang sudah selesai dikodekan.'),
('o5-C6-3', 'q5000005-0000-0000-0000-000000000006', 'Maintenance', 0, 'Keliru. Maintenance adalah pemeliharaan sistem setelah dirilis.'),
('o5-C6-4', 'q5000005-0000-0000-0000-000000000006', 'Hosting', 0, 'Keliru. Hosting adalah penyediaan server untuk menjalankan website.'),
('o5-C7-1', 'q5000005-0000-0000-0000-000000000007', 'Menunjukkan alur interaksi pengguna', 10, 'Tepat! User flow pada prototype memetakan langkah demi langkah interaksi pengguna dari awal hingga tujuan tercapai.'),
('o5-C7-2', 'q5000005-0000-0000-0000-000000000007', 'Menyimpan kode program', 0, 'Keliru. Penyimpanan kode program dilakukan di repository Git.'),
('o5-C7-3', 'q5000005-0000-0000-0000-000000000007', 'Membuat database', 0, 'Keliru. User flow tidak membuat skema database.'),
('o5-C7-4', 'q5000005-0000-0000-0000-000000000007', 'Menentukan harga', 0, 'Keliru. User flow berfokus pada pengalaman navigasi pengguna.'),
('o5-C8-1', 'q5000005-0000-0000-0000-000000000008', 'Mengabaikan kebutuhan pengguna', 10, 'Tepat! Desain yang hanya mengejar estetika tanpa menjawab kebutuhan pengguna akan gagal saat diuji.'),
('o5-C8-2', 'q5000005-0000-0000-0000-000000000008', 'Menguji desain ke pengguna', 0, 'Keliru. Menguji desain ke pengguna justru praktik terbaik yang wajib dilakukan.'),
('o5-C8-3', 'q5000005-0000-0000-0000-000000000008', 'Membuat alur sederhana', 0, 'Keliru. Alur yang sederhana dan jelas memudahkan pengguna mencapai tujuan.'),
('o5-C8-4', 'q5000005-0000-0000-0000-000000000008', 'Melakukan validasi', 0, 'Keliru. Validasi adalah langkah penting untuk memastikan solusi tepat sasaran.'),
('o5-C9-1', 'q5000005-0000-0000-0000-000000000009', 'Perbaikan desain secara berulang berdasarkan feedback', 10, 'Tepat! Iterasi adalah siklus uji, evaluasi masukan, dan penyempurnaan desain secara bertahap.'),
('o5-C9-2', 'q5000005-0000-0000-0000-000000000009', 'Menghapus desain lama', 0, 'Keliru. Iterasi memperbaiki dan menyempurnakan desain berdasarkan data, bukan membuang tanpa analisis.'),
('o5-C9-3', 'q5000005-0000-0000-0000-000000000009', 'Membuat database baru', 0, 'Keliru. Iterasi desain berfokus pada penyempurnaan antarmuka dan pengalaman pengguna.'),
('o5-C9-4', 'q5000005-0000-0000-0000-000000000009', 'Menambah biaya proyek', 0, 'Keliru. Iterasi di tahap prototype justru menekan biaya perbaikan di tahap produksi.'),
('o5-C10-1', 'q5000005-0000-0000-0000-000000000010', 'Test Early, Learn Fast', 10, 'Tepat! Prinsip "Test Early, Learn Fast" mendorong pengujian sedini mungkin agar tim cepat belajar dan beradaptasi.'),
('o5-C10-2', 'q5000005-0000-0000-0000-000000000010', 'Build Fast, Ignore Users', 0, 'Keliru. Mengabaikan pengguna bertentangan dengan prinsip User-Centered Design.'),
('o5-C10-3', 'q5000005-0000-0000-0000-000000000010', 'Launch First, Fix Later', 0, 'Keliru. Merilis produk tanpa validasi prototype membuat biaya perbaikan membengkak.'),
('o5-C10-4', 'q5000005-0000-0000-0000-000000000010', 'Design Without Research', 0, 'Keliru. Desain tanpa riset hanya menghasilkan solusi berbasis asumsi.');
INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES
('er-0000005-0000-0000-0000-000000000001', 'q5000002-0000-0000-0000-000000000001', 'Prototype adalah representasi atau simulasi produk digital yang digunakan untuk menguji ide, alur, dan interaksi pengguna sebelum produk dikembangkan sepenuhnya.', ARRAY['prototype', 'simulasi', 'representasi produk', 'pengujian', 'interaksi pengguna', 'representasi', 'uji']::text[], '{"0":"Tidak relevan","7":"Prototype adalah desain aplikasi (terlalu umum dan tidak menjelaskan tujuan prototype)","8":"Prototype adalah desain awal aplikasi (belum menjelaskan fungsi simulasi dan pengujian)","9":"Prototype adalah contoh awal produk untuk diuji","10":"Menjelaskan representasi/simulasi produk untuk pengujian ide, alur, dan interaksi pengguna"}'::jsonb),
('er-0000005-0000-0000-0000-000000000002', 'q5000002-0000-0000-0000-000000000002', 'Prototype membantu memvalidasi ide, menemukan masalah usability lebih awal, mengurangi risiko kesalahan, dan memperoleh feedback pengguna sebelum pengembangan dilakukan.', ARRAY['validasi', 'feedback', 'usability', 'risiko', 'perbaikan', 'masalah']::text[], '{"0":"Tidak relevan","7":"Prototype dibuat sebelum coding (menjelaskan urutan, bukan manfaat)","8":"Prototype membantu desainer bekerja lebih mudah (belum menjelaskan validasi dan pengurangan risiko)","9":"Prototype membantu menemukan masalah sebelum produk dibuat","10":"Menjelaskan validasi ide, penemuan masalah usability lebih awal, pengurangan risiko, dan feedback pengguna"}'::jsonb),
('er-0000005-0000-0000-0000-000000000003', 'q5000002-0000-0000-0000-000000000003', 'Low-Fidelity Prototype memiliki detail rendah dan digunakan untuk menguji struktur serta alur. High-Fidelity Prototype memiliki tampilan dan interaksi yang mendekati produk akhir.', ARRAY['low fidelity', 'high fidelity', 'detail rendah', 'produk akhir', 'interaksi', 'struktur']::text[], '{"0":"Tidak relevan","8":"Menjelaskan salah satu jenis atau perbedaan secara umum","10":"Menjelaskan perbedaan tingkat detail, tampilan, interaksi, dan fungsi pengujian kedua jenis prototype"}'::jsonb),
('er-0000005-0000-0000-0000-000000000004', 'q5000002-0000-0000-0000-000000000004', 'Clickable prototype memungkinkan pengguna mencoba alur interaksi secara nyata sehingga feedback yang diperoleh lebih akurat.', ARRAY['clickable', 'interaksi', 'simulasi', 'feedback', 'alur', 'nyata']::text[], '{"0":"Tidak relevan","8":"Menjelaskan bahwa prototype dapat diklik secara umum","10":"Menjelaskan kemampuan pengguna mensimulasikan alur interaksi secara nyata sehingga menghasilkan feedback akurat"}'::jsonb),
('er-0000005-0000-0000-0000-000000000005', 'q5000002-0000-0000-0000-000000000005', 'Feedback membantu mengidentifikasi kekurangan desain, memvalidasi asumsi, dan meningkatkan kualitas solusi sesuai kebutuhan pengguna.', ARRAY['feedback', 'validasi', 'kebutuhan pengguna', 'perbaikan desain', 'kekurangan', 'asumsi']::text[], '{"0":"Tidak relevan","8":"Menjelaskan bahwa feedback membantu memperbaiki desain secara umum","10":"Menjelaskan peran feedback dalam mengidentifikasi kekurangan desain, memvalidasi asumsi, dan meningkatkan solusi"}'::jsonb),
('er-0000005-0000-0000-0000-000000000006', 'q5000004-0000-0000-0000-000000000001', 'Button berfungsi sebagai elemen interaktif yang digunakan pengguna untuk menjalankan suatu aksi atau berpindah ke proses berikutnya.', ARRAY['button', 'aksi', 'interaksi', 'navigasi', 'elemen interaktif', 'proses']::text[], '{"0":"Tidak relevan","8":"Menjelaskan fungsi tombol untuk diklik secara umum","10":"Menjelaskan button sebagai elemen interaktif pemicu aksi atau navigasi proses"}'::jsonb),
('er-0000005-0000-0000-0000-000000000007', 'q5000004-0000-0000-0000-000000000002', 'Input Field digunakan untuk menerima data atau informasi yang dimasukkan oleh pengguna.', ARRAY['input field', 'memasukkan data', 'pengguna', 'data', 'informasi']::text[], '{"0":"Tidak relevan","8":"Menjelaskan tempat mengetik teks secara umum","10":"Menjelaskan fungsi input field untuk menerima data atau informasi dari pengguna"}'::jsonb),
('er-0000005-0000-0000-0000-000000000008', 'q5000004-0000-0000-0000-000000000003', 'Dropdown lebih cocok ketika pilihan cukup banyak dan perlu menghemat ruang layar, sedangkan Radio Button cocok untuk pilihan yang jumlahnya sedikit.', ARRAY['dropdown', 'banyak pilihan', 'hemat ruang', 'radio button', 'sedikit']::text[], '{"0":"Tidak relevan","8":"Menyebutkan salah satu kondisi penggunaan dropdown atau radio button","10":"Membandingkan penggunaan dropdown (banyak pilihan dan hemat ruang layar) dengan radio button (pilihan sedikit)"}'::jsonb),
('er-0000005-0000-0000-0000-000000000009', 'q5000004-0000-0000-0000-000000000004', 'Konsistensi membantu pengguna memahami antarmuka lebih cepat, mengurangi kebingungan, dan meningkatkan pengalaman penggunaan.', ARRAY['konsistensi', 'pengalaman pengguna', 'kemudahan', 'mengurangi kebingungan', 'cepat']::text[], '{"0":"Tidak relevan","8":"Menyebutkan desain terlihat rapi dan seragam secara umum","10":"Menjelaskan manfaat konsistensi dalam mempercepat pemahaman antarmuka, mengurangi kebingungan, dan meningkatkan UX"}'::jsonb),
('er-0000005-0000-0000-0000-000000000010', 'q5000004-0000-0000-0000-000000000005', 'User Testing adalah proses menguji prototype kepada pengguna nyata untuk mengevaluasi kemudahan penggunaan serta menemukan masalah yang perlu diperbaiki.', ARRAY['user testing', 'pengguna nyata', 'evaluasi', 'usability', 'masalah', 'kemudahan']::text[], '{"0":"Tidak relevan","8":"Menjelaskan pengujian aplikasi kepada pengguna secara umum","10":"Menjelaskan pengujian prototype pada pengguna nyata untuk mengevaluasi kemudahan penggunaan dan menemukan masalah"}'::jsonb),
('er-0000005-0000-0000-0000-000000000011', 'q5000006-0000-0000-0000-000000000001', 'CTA berfungsi mengarahkan pengguna untuk melakukan tindakan tertentu seperti mendaftar, membeli, atau menghubungi layanan.', ARRAY['cta', 'tindakan', 'konversi', 'pengguna', 'mengarahkan']::text[], '{"0":"Tidak relevan","8":"Menyebutkan tombol ajakan secara umum","10":"Menjelaskan fungsi CTA dalam mengarahkan pengguna melakukan tindakan spesifik atau konversi beserta contoh"}'::jsonb),
('er-0000005-0000-0000-0000-000000000012', 'q5000006-0000-0000-0000-000000000002', 'Agar dapat diketahui apakah pengguna mampu menyelesaikan tugasnya dengan mudah dan tanpa hambatan.', ARRAY['user flow', 'tugas pengguna', 'kemudahan', 'hambatan', 'menyelesaikan tugas']::text[], '{"0":"Tidak relevan","8":"Menyebutkan untuk mengecek alur halaman secara umum","10":"Menjelaskan tujuan pengujian alur untuk memastikan pengguna mampu menyelesaikan tugas dengan mudah tanpa hambatan"}'::jsonb),
('er-0000005-0000-0000-0000-000000000013', 'q5000006-0000-0000-0000-000000000003', 'Iterasi desain adalah proses memperbaiki dan menyempurnakan desain secara berulang berdasarkan hasil evaluasi dan feedback.', ARRAY['iterasi', 'perbaikan berulang', 'feedback', 'evaluasi', 'menyempurnakan']::text[], '{"0":"Tidak relevan","8":"Menyebutkan perbaikan desain secara umum","10":"Menjelaskan proses perbaikan dan penyempurnaan desain secara berulang berdasarkan hasil evaluasi dan feedback"}'::jsonb),
('er-0000005-0000-0000-0000-000000000014', 'q5000006-0000-0000-0000-000000000004', 'Karena masalah dapat ditemukan dan diperbaiki sebelum masuk tahap coding yang lebih mahal dan kompleks.', ARRAY['biaya', 'menemukan masalah lebih awal', 'coding', 'efisiensi', 'mahal']::text[], '{"0":"Tidak relevan","8":"Menyebutkan menghemat biaya pengembangan secara umum","10":"Menjelaskan bahwa masalah dapat ditemukan dan diperbaiki lebih awal sebelum tahap coding yang mahal dan kompleks"}'::jsonb),
('er-0000005-0000-0000-0000-000000000015', 'q5000006-0000-0000-0000-000000000005', 'Prinsip ini menekankan pentingnya menguji desain sedini mungkin agar tim dapat belajar dari feedback pengguna dan melakukan perbaikan lebih cepat.', ARRAY['test early', 'learn fast', 'feedback', 'perbaikan cepat', 'validasi pengguna', 'sedini mungkin']::text[], '{"0":"Tidak relevan","7":"Testing dilakukan sebelum produk selesai (terlalu umum)","8":"Melakukan testing sejak awal proyek (belum menjelaskan proses pembelajaran dan iterasi berdasarkan feedback)","9":"Menguji desain lebih awal untuk mendapatkan masukan","10":"Menjelaskan pengujian desain sedini mungkin agar tim belajar dari feedback pengguna dan melakukan perbaikan lebih cepat"}'::jsonb);
